/* The box sits a border and padding outside the text, so the text lines up with the content around it and the hover surface reaches past it. */
.root { --pad-x: 8px; --pad-y: 3px; position: relative; display: grid; min-width: 0; margin-inline-start: calc(-1 * (var(--pad-x) + 1px)); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
/* Whole-pixel line heights: an input centres its text by rounding, so a fractional line would sit the field a pixel below the display. */
.root[data-variant="title"] { --size: var(--text-xl); --leading: round(var(--size) * 1.3, 2px); --weight: 500; --ink: var(--foreground); }
.root[data-variant="body"] { --pad-y: 5px; --size: var(--text-sm); --leading: round(var(--size) * 1.5, 1px); --weight: 400; --ink: var(--text-secondary); }
/* Room for the actions is reserved in every state, so the text never rewraps when editing starts. */
/* Inter at every size here: a heading host keeps its semantics but not the display face. */
.line { display: block; min-width: 0; margin: 0; padding-inline-end: 66px; color: var(--ink); font-family: var(--font-body); font-size: var(--size); font-weight: var(--weight); line-height: var(--leading); letter-spacing: var(--tracking-body); }
.root[data-multiline] .line { padding-inline-end: 38px; }
.box { position: relative; display: inline-block; max-width: 100%; vertical-align: top; }
.root[data-multiline] .box { display: block; }

/* Display and field share every metric: border, padding, font, and line height. Only the frame behind them changes. */
.display, .control { box-sizing: border-box; margin: 0; padding: var(--pad-y) var(--pad-x); border: 1px solid transparent; border-radius: var(--radius-control); background: transparent; color: inherit; font: inherit; font-feature-settings: inherit; letter-spacing: inherit; word-spacing: inherit; line-height: var(--leading); text-align: left; text-indent: 0; text-transform: none; -webkit-tap-highlight-color: transparent; }
.display { position: relative; z-index: 1; display: block; max-width: 100%; cursor: text; }
.root[data-multiline] .display { width: 100%; }
.root[data-editing] .display { visibility: hidden; }
/* While editing, a single line keeps a little extra room, so the next character never has to wait for the box. */
.root[data-editing]:not([data-multiline]) .display { min-width: 5em; padding-inline-end: calc(var(--pad-x) + 16px); }
.display[aria-disabled="true"] { cursor: progress; }
.display:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.layer { position: relative; display: block; transition: opacity var(--duration-standard) var(--ease-standard); }
.layer[data-empty] { color: var(--text-muted); }
/* An optimistic save shows the new text at once, a little quieter until the save lands; then it settles to full strength. */
.root[data-phase="saving"] .layer { opacity: .5; transition-duration: var(--duration-fast); }
.text { display: block; overflow: hidden; text-overflow: ellipsis; white-space: pre; }
.root[data-multiline] .text { overflow: visible; white-space: pre-wrap; overflow-wrap: break-word; }
.control { position: absolute; top: 0; left: 0; z-index: 2; width: 100%; height: 100%; outline: none; resize: none; overflow: hidden; caret-color: var(--foreground); }
/* The frame carries the focus ring for the field, so the field itself never draws a second one. */
.control:focus-visible { outline: none; }
.control::placeholder { color: var(--text-muted); opacity: 1; }
textarea.control { white-space: pre-wrap; overflow-wrap: break-word; }

/* The frame is the only surface: a hover tint at rest, a bordered field while editing, a soft danger wash when a save fails. */
.frame { position: absolute; top: 0; bottom: 0; left: 0; z-index: 0; box-sizing: border-box; border: 1px solid transparent; border-radius: var(--radius-control); background: transparent; pointer-events: none; transition: background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
.root[data-multiline] .frame { right: 0; }
@media (hover: hover) and (pointer: fine) {
  .display:not([aria-disabled="true"]):hover ~ .frame { background: var(--surface-muted); }
  .pencil { opacity: 0; transition: opacity var(--duration-fast) var(--ease-standard); }
  .display:hover ~ .frame .pencil, .display:focus-visible ~ .frame .pencil, .pencil:hover { opacity: 1; }
}
.root[data-editing] .frame { border-color: var(--foreground); background: var(--surface); box-shadow: 0 0 0 3px var(--focus-ring); }
.root[data-invalid] .frame { border-color: var(--danger); box-shadow: 0 0 0 3px color-mix(in oklch, var(--danger) 24%, transparent); }
.root[data-flash="on"] .frame { border-color: color-mix(in oklch, var(--danger) 30%, transparent); background: color-mix(in oklch, var(--danger) 9%, transparent); }
/* The wash leaves slowly, without any movement, once the message has been read. */
.root[data-flash="off"] .frame { transition-duration: var(--duration-considered); }

/* The slot rides on the frame's edge, so it follows the width morph instead of jumping to the new width. */
.slot { position: absolute; top: 50%; left: calc(100% + 6px); display: grid; min-height: 28px; margin-top: -14px; pointer-events: auto; }
.root[data-multiline] .slot { top: 0; left: calc(100% + 8px); margin-top: calc(var(--pad-y) + var(--leading) / 2 - 13px); }
.slotItem { display: grid; grid-area: 1 / 1; min-height: 28px; place-items: center start; }
.actions { display: flex; gap: 4px; }
.root[data-multiline] .actions { flex-direction: column; }
.save, .cancel { display: grid; width: 28px; height: 28px; flex: none; place-items: center; padding: 0; border: 1px solid transparent; border-radius: var(--radius-pill); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); }
.save { background: var(--foreground); color: var(--background); }
.cancel { border-color: var(--border); background: var(--surface); color: var(--text-secondary); }
.save:active, .cancel:active { transform: scale(.96); }
@media (hover: hover) and (pointer: fine) { .save:hover { background: color-mix(in oklch, var(--foreground) 86%, var(--background)); } .cancel:hover { border-color: var(--border-strong); background: var(--surface-muted); color: var(--foreground); } }
.save:focus-visible, .cancel:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.pencil { margin-left: 2px; color: var(--text-muted); cursor: pointer; }
.spinner { display: block; width: 14px; height: 14px; margin-left: 2px; border: 1.5px solid var(--text-muted); border-right-color: transparent; border-radius: var(--radius-pill); animation: spin .7s linear infinite; }
.saved { display: grid; margin-left: 1px; place-items: center; color: var(--success); }
.failedIcon { margin-left: 1px; color: var(--danger); }

/* The message row opens from a true zero; its spacing lives inside the clipped slot. */
.reveal { display: block; overflow: hidden; }
.revealInner { position: relative; display: block; }
.message { display: flex; align-items: flex-start; gap: 6px; padding: 6px var(--pad-x) 4px calc(var(--pad-x) + 1px); color: var(--text-secondary); font-size: var(--text-xs); font-weight: 400; line-height: var(--leading-body); }
.message[data-tone="error"] { color: var(--danger); }
.messageIcon { flex: none; margin-top: 2px; color: var(--danger); }
.retry { margin: 0 0 0 2px; padding: 0; border: 0; border-radius: 4px; background: none; color: var(--foreground); font: inherit; font-weight: 500; text-decoration: underline; text-decoration-color: var(--border-strong); text-underline-offset: 3px; cursor: pointer; }
@media (hover: hover) and (pointer: fine) { .retry:hover { text-decoration-color: currentColor; } }
.retry:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation: none; border-right-color: var(--text-muted); border-top-color: transparent; } .layer, .save, .cancel, .pencil { transition: none; } }
